const RegisterBankInfo::ValueMapping *
AArch64GenRegisterBankInfo::getCopyMapping(unsigned DstBankID,
                                           unsigned SrcBankID,
                                           const TypeSize Size) const {

  const ValueMapping *DstMapping =
      AArch64::getGeneratedValueMapping(DstBankID, Size);
  const ValueMapping *SrcMapping =
      AArch64::getGeneratedValueMapping(SrcBankID, Size);
  return getOperandsMapping({DstMapping, SrcMapping});
}

AArch64RegisterBankInfo::AArch64RegisterBankInfo(
    const TargetRegisterInfo &TRI) {}

unsigned AArch64RegisterBankInfo::copyCost(const RegisterBank &A,
                                           const RegisterBank &B,
                                           const TypeSize Size) const {
  // What do we do with different size?
  // copy are same size.
  // Will introduce other hooks for different size:
  // * extract cost.
  // * build_sequence cost.

  // Copy from (resp. to) GPR to (resp. from) FPR involves FMOV.
  // FIXME: This should be deduced from the scheduling model.
  if (&A == &AArch64::GPRRegBank && &B == &AArch64::FPRRegBank)
    // FMOVXDr or FMOVWSr.
    return 5;
  if (&A == &AArch64::FPRRegBank && &B == &AArch64::GPRRegBank)
    // FMOVDXr or FMOVSWr.
    return 4;

  return RegisterBankInfo::copyCost(A, B, Size);
}

const RegisterBank &
AArch64RegisterBankInfo::getRegBankFromRegClass(const TargetRegisterClass &RC,
                                                LLT Ty) const {
  switch (RC.getID()) {
  case AArch64::GPR64sponlyRegClassID:
    return AArch64::GPRRegBank;
  default:
    return AArch64GenRegisterBankInfo::getRegBankFromRegClass(RC, Ty);
  }
}

RegisterBankInfo::InstructionMappings
AArch64RegisterBankInfo::getInstrAlternativeMappings(
    const MachineInstr &MI) const {
  if (InstructionMappings Mappings = getGeneratedInstrAltMappings(MI);
      !Mappings.empty())
    return Mappings;

  return RegisterBankInfo::getInstrAlternativeMappings(MI);
}

static bool preferGPRForFPImm(const MachineInstr &MI,
                              const MachineRegisterInfo &MRI,
                              const AArch64Subtarget &STI) {
  assert(MI.getOpcode() == TargetOpcode::G_FCONSTANT);
  Register Dst = MI.getOperand(0).getReg();
  LLT Ty = MRI.getType(Dst);

  unsigned Size = Ty.getSizeInBits();
  if (Size != 16 && Size != 32 && Size != 64)
    return false;

  EVT VT = EVT::getFloatingPointVT(Size);
  const AArch64TargetLowering *TLI = STI.getTargetLowering();

  const APFloat Imm = MI.getOperand(1).getFPImm()->getValueAPF();
  const APInt ImmBits = Imm.bitcastToAPInt();

  // If all the uses are stores use a gpr constant
  if (all_of(MRI.use_nodbg_instructions(Dst), [&](const MachineInstr &UseMI) {
        return UseMI.getOpcode() == TargetOpcode::G_STORE &&
               UseMI.getOperand(0).getReg() == Dst;
      }))
    return true;

  // Check if we can encode this as a movi. Note, we only have one pattern so
  // far for movis, hence the one check.
  if (Size == 32) {
    uint64_t Val = APInt::getSplat(64, ImmBits).getZExtValue();
    if (AArch64_AM::isAdvSIMDModImmType4(Val))
      return false;
  }

  // We want to use GPR when the value cannot be encoded as the immediate value
  // of a fmov and when it will not result in a constant pool load. As
  // AArch64TargetLowering::isFPImmLegal is used by the instruction selector
  // to choose whether to emit a constant pool load, negating this check will
  // ensure it would not have become a constant pool load.
  bool OptForSize =
      shouldOptimizeForSize(&MI.getMF()->getFunction(), nullptr, nullptr);
  bool IsLegal = TLI->isFPImmLegal(Imm, VT, OptForSize);
  bool IsFMov = TLI->isFPImmLegalAsFMov(Imm, VT);
  return !IsFMov && IsLegal;
}

// Some of the instructions in applyMappingImpl attempt to anyext small values.
// It may be that these values come from a G_CONSTANT that has been expanded to
// 32 bits and then truncated. If this is the case, we shouldn't insert an
// anyext and should instead make use of the G_CONSTANT directly, deleting the
// trunc if possible.
static bool foldTruncOfI32Constant(MachineInstr &MI, unsigned OpIdx,
                                   MachineRegisterInfo &MRI) {
  MachineOperand &Op = MI.getOperand(OpIdx);

  Register ScalarReg = Op.getReg();
  MachineInstr *TruncMI = MRI.getVRegDef(ScalarReg);
  if (!TruncMI || TruncMI->getOpcode() != TargetOpcode::G_TRUNC)
    return false;

  Register TruncSrc = TruncMI->getOperand(1).getReg();
  MachineInstr *SrcDef = MRI.getVRegDef(TruncSrc);
  if (!SrcDef || SrcDef->getOpcode() != TargetOpcode::G_CONSTANT)
    return false;

  LLT TruncSrcTy = MRI.getType(TruncSrc);
  if (!TruncSrcTy.isScalar() || TruncSrcTy.getSizeInBits() != 32)
    return false;

  // Avoid truncating and extending a constant, this helps with selection.
  Op.setReg(TruncSrc);
  MRI.setRegBank(TruncSrc, AArch64::GPRRegBank);

  if (MRI.use_empty(ScalarReg))
    TruncMI->eraseFromParent();

  return true;
}

void AArch64RegisterBankInfo::applyMappingImpl(
    MachineIRBuilder &Builder, const OperandsMapper &OpdMapper) const {
  MachineInstr &MI = OpdMapper.getMI();
  MachineRegisterInfo &MRI = OpdMapper.getMRI();

  switch (MI.getOpcode()) {
  case TargetOpcode::G_CONSTANT: {
    Register Dst = MI.getOperand(0).getReg();
    [[maybe_unused]] LLT DstTy = MRI.getType(Dst);
    assert(MRI.getRegBank(Dst) == &AArch64::GPRRegBank && DstTy.isScalar() &&
           DstTy.getSizeInBits() < 32 &&
           "Expected a scalar smaller than 32 bits on a GPR.");
    Builder.setInsertPt(*MI.getParent(), std::next(MI.getIterator()));
    Register ExtReg = MRI.createGenericVirtualRegister(LLT::integer(32));
    Builder.buildTrunc(Dst, ExtReg);

    APInt Val = MI.getOperand(1).getCImm()->getValue().zext(32);
    LLVMContext &Ctx = Builder.getMF().getFunction().getContext();
    MI.getOperand(1).setCImm(ConstantInt::get(Ctx, Val));
    MI.getOperand(0).setReg(ExtReg);
    MRI.setRegBank(ExtReg, AArch64::GPRRegBank);

    return applyDefaultMapping(OpdMapper);
  }
  case TargetOpcode::G_FCONSTANT: {
    Register Dst = MI.getOperand(0).getReg();
    assert(MRI.getRegBank(Dst) == &AArch64::GPRRegBank &&
           "Expected Dst to be on a GPR.");
    const APFloat &Imm = MI.getOperand(1).getFPImm()->getValueAPF();
    APInt Bits = Imm.bitcastToAPInt();
    Builder.setInsertPt(*MI.getParent(), MI.getIterator());
    if (Bits.getBitWidth() < 32) {
      Register ExtReg = MRI.createGenericVirtualRegister(LLT::integer(32));
      Builder.buildConstant(ExtReg, Bits.zext(32));
      Builder.buildTrunc(Dst, ExtReg);
      MRI.setRegBank(ExtReg, AArch64::GPRRegBank);
    } else {
      Builder.buildConstant(Dst, Bits);
    }
    MI.eraseFromParent();
    return;
  }
  case TargetOpcode::G_STORE: {
    Register Dst = MI.getOperand(0).getReg();
    LLT Ty = MRI.getType(Dst);

    if (MRI.getRegBank(Dst) == &AArch64::GPRRegBank && Ty.isScalar() &&
        Ty.getSizeInBits() < 32) {

      if (foldTruncOfI32Constant(MI, 0, MRI))
        return applyDefaultMapping(OpdMapper);

      Builder.setInsertPt(*MI.getParent(), MI.getIterator());
      auto Ext = Builder.buildAnyExt(LLT::integer(32), Dst);
      MI.getOperand(0).setReg(Ext.getReg(0));
      MRI.setRegBank(Ext.getReg(0), AArch64::GPRRegBank);
    }
    return applyDefaultMapping(OpdMapper);
  }
  case TargetOpcode::G_LOAD: {
    Register Dst = MI.getOperand(0).getReg();
    LLT Ty = MRI.getType(Dst);
    if (MRI.getRegBank(Dst) == &AArch64::GPRRegBank && Ty.isScalar() &&
        Ty.getSizeInBits() < 32) {
      Builder.setInsertPt(*MI.getParent(), std::next(MI.getIterator()));
      Register ExtReg = MRI.createGenericVirtualRegister(LLT::integer(32));
      Builder.buildTrunc(Dst, ExtReg);
      MI.getOperand(0).setReg(ExtReg);
      MRI.setRegBank(ExtReg, AArch64::GPRRegBank);
    }
    [[fallthrough]];
  }
  case TargetOpcode::G_OR:
  case TargetOpcode::G_BITCAST:
    // Those ID must match getInstrAlternativeMappings.
    assert((OpdMapper.getInstrMapping().getID() >= 1 &&
            OpdMapper.getInstrMapping().getID() <= 4) &&
           "Don't know how to handle that ID");
    return applyDefaultMapping(OpdMapper);
  case TargetOpcode::G_SPLAT_VECTOR: {
    if (foldTruncOfI32Constant(MI, 1, MRI))
      return applyDefaultMapping(OpdMapper);

    // Extend smaller gpr to 32-bits
    assert(MRI.getType(MI.getOperand(1).getReg()).getSizeInBits() < 32 &&
           "Expected sources smaller than 32-bits");
    Builder.setInsertPt(*MI.getParent(), MI.getIterator());

    Register ConstReg =
        Builder.buildAnyExt(LLT::integer(32), MI.getOperand(1).getReg())
            .getReg(0);
    MRI.setRegBank(ConstReg, AArch64::GPRRegBank);
    MI.getOperand(1).setReg(ConstReg);

    return applyDefaultMapping(OpdMapper);
  }
  default:
    llvm_unreachable("Don't know how to handle that operation");
  }
}

/// \returns true if a given intrinsic only uses and defines FPRs.
static bool isFPIntrinsic(const MachineRegisterInfo &MRI,
                          const MachineInstr &MI) {
  // TODO: Add more intrinsics.
  switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
  default:
    return false;
  case Intrinsic::aarch64_neon_uaddlv:
  case Intrinsic::aarch64_neon_uaddv:
  case Intrinsic::aarch64_neon_saddv:
  case Intrinsic::aarch64_neon_umaxv:
  case Intrinsic::aarch64_neon_smaxv:
  case Intrinsic::aarch64_neon_uminv:
  case Intrinsic::aarch64_neon_sminv:
  case Intrinsic::aarch64_neon_faddv:
  case Intrinsic::aarch64_neon_fmaxv:
  case Intrinsic::aarch64_neon_fminv:
  case Intrinsic::aarch64_neon_fmaxnmv:
  case Intrinsic::aarch64_neon_fminnmv:
  case Intrinsic::aarch64_neon_fmulx:
  case Intrinsic::aarch64_neon_frecpe:
  case Intrinsic::aarch64_neon_frecps:
  case Intrinsic::aarch64_neon_frecpx:
  case Intrinsic::aarch64_neon_frsqrte:
  case Intrinsic::aarch64_neon_frsqrts:
  case Intrinsic::aarch64_neon_facge:
  case Intrinsic::aarch64_neon_facgt:
  case Intrinsic::aarch64_neon_fabd:
  case Intrinsic::aarch64_neon_sqrdmlah:
  case Intrinsic::aarch64_neon_sqrdmlsh:
  case Intrinsic::aarch64_neon_sqrdmulh:
  case Intrinsic::aarch64_neon_suqadd:
  case Intrinsic::aarch64_neon_usqadd:
  case Intrinsic::aarch64_neon_uqadd:
  case Intrinsic::aarch64_neon_sqadd:
  case Intrinsic::aarch64_neon_uqsub:
  case Intrinsic::aarch64_neon_sqsub:
  case Intrinsic::aarch64_neon_sqdmulh:
  case Intrinsic::aarch64_neon_sqdmulls_scalar:
  case Intrinsic::aarch64_neon_srshl:
  case Intrinsic::aarch64_neon_urshl:
  case Intrinsic::aarch64_neon_sqshl:
  case Intrinsic::aarch64_neon_uqshl:
  case Intrinsic::aarch64_neon_sqrshl:
  case Intrinsic::aarch64_neon_uqrshl:
  case Intrinsic::aarch64_neon_ushl:
  case Intrinsic::aarch64_neon_sshl:
  case Intrinsic::aarch64_neon_sqshrn:
  case Intrinsic::aarch64_neon_sqshrun:
  case Intrinsic::aarch64_neon_sqrshrn:
  case Intrinsic::aarch64_neon_sqrshrun:
  case Intrinsic::aarch64_neon_uqshrn:
  case Intrinsic::aarch64_neon_uqrshrn:
  case Intrinsic::aarch64_neon_sqneg:
  case Intrinsic::aarch64_neon_sqabs:
  case Intrinsic::aarch64_neon_scalar_uqxtn:
  case Intrinsic::aarch64_neon_scalar_sqxtn:
  case Intrinsic::aarch64_neon_scalar_sqxtun:
  case Intrinsic::aarch64_crypto_sha1h:
  case Intrinsic::aarch64_crypto_sha1c:
  case Intrinsic::aarch64_crypto_sha1p:
  case Intrinsic::aarch64_crypto_sha1m:
  case Intrinsic::aarch64_sisd_fcvtxn:
  case Intrinsic::aarch64_sisd_fabd:
    return true;
  case Intrinsic::aarch64_neon_saddlv: {
    const LLT SrcTy = MRI.getType(MI.getOperand(2).getReg());
    return SrcTy.getElementType().getSizeInBits() >= 16 &&
           SrcTy.getElementCount().getFixedValue() >= 4;
  }
  }
}

bool AArch64RegisterBankInfo::isPHIWithFPConstraints(
    const MachineInstr &MI, const MachineRegisterInfo &MRI,
    const AArch64RegisterInfo &TRI, const unsigned Depth) const {
  if (!MI.isPHI() || Depth > MaxFPRSearchDepth)
    return false;

  return any_of(MRI.use_nodbg_instructions(MI.getOperand(0).getReg()),
                [&](const MachineInstr &UseMI) {
                  if (onlyUsesFP(UseMI, MRI, TRI, Depth + 1))
                    return true;
                  return isPHIWithFPConstraints(UseMI, MRI, TRI, Depth + 1);
                });
}

bool AArch64RegisterBankInfo::hasFPConstraints(const MachineInstr &MI,
                                               const MachineRegisterInfo &MRI,
                                               const AArch64RegisterInfo &TRI,
                                               unsigned Depth) const {
  unsigned Op = MI.getOpcode();
  if (Op == TargetOpcode::G_INTRINSIC && isFPIntrinsic(MRI, MI))
    return true;

  // Do we have an explicit floating point instruction?
  if (isPreISelGenericFloatingPointOpcode(Op))
    return true;

  // No. Check if we have a copy-like instruction. If we do, then we could
  // still be fed by floating point instructions.
  if (Op != TargetOpcode::COPY && !MI.isPHI() &&
      !isPreISelGenericOptimizationHint(Op))
    return false;

  // Check if we already know the register bank.
  auto *RB = getRegBank(MI.getOperand(0).getReg(), MRI, TRI);
  if (RB == &AArch64::FPRRegBank)
    return true;
  if (RB == &AArch64::GPRRegBank)
    return false;

  // We don't know anything.
  //
  // If we have a phi, we may be able to infer that it will be assigned a FPR
  // based off of its inputs.
  if (!MI.isPHI() || Depth > MaxFPRSearchDepth)
    return false;

  return any_of(MI.explicit_uses(), [&](const MachineOperand &Op) {
    return Op.isReg() &&
           onlyDefinesFP(*MRI.getVRegDef(Op.getReg()), MRI, TRI, Depth + 1);
  });
}

bool AArch64RegisterBankInfo::onlyUsesFP(const MachineInstr &MI,
                                         const MachineRegisterInfo &MRI,
                                         const AArch64RegisterInfo &TRI,
                                         unsigned Depth) const {
  switch (MI.getOpcode()) {
  case TargetOpcode::G_BITCAST: {
    Register DstReg = MI.getOperand(0).getReg();
    return all_of(MRI.use_nodbg_instructions(DstReg),
                  [&](const MachineInstr &UseMI) {
                    return onlyUsesFP(UseMI, MRI, TRI, Depth + 1) ||
                           prefersFPUse(UseMI, MRI, TRI);
                  });
  }

  case TargetOpcode::G_FPTOSI:
  case TargetOpcode::G_FPTOUI:
  case TargetOpcode::G_FPTOSI_SAT:
  case TargetOpcode::G_FPTOUI_SAT:
  case TargetOpcode::G_FCMP:
  case TargetOpcode::G_LROUND:
  case TargetOpcode::G_LLROUND:
  case TargetOpcode::G_CLMUL:
  case AArch64::G_PMULL:
  case AArch64::G_SLI:
  case AArch64::G_SRI:
  case AArch64::G_FPTRUNC_ODD:
    return true;
  case TargetOpcode::G_INTRINSIC:
    switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
    case Intrinsic::aarch64_neon_fcvtas:
    case Intrinsic::aarch64_neon_fcvtau:
    case Intrinsic::aarch64_neon_fcvtzs:
    case Intrinsic::aarch64_neon_fcvtzu:
    case Intrinsic::aarch64_neon_fcvtms:
    case Intrinsic::aarch64_neon_fcvtmu:
    case Intrinsic::aarch64_neon_fcvtns:
    case Intrinsic::aarch64_neon_fcvtnu:
    case Intrinsic::aarch64_neon_fcvtps:
    case Intrinsic::aarch64_neon_fcvtpu:
      return true;
    default:
      break;
    }
    break;
  default:
    break;
  }
  return hasFPConstraints(MI, MRI, TRI, Depth);
}

bool AArch64RegisterBankInfo::onlyDefinesFP(const MachineInstr &MI,
                                            const MachineRegisterInfo &MRI,
                                            const AArch64RegisterInfo &TRI,
                                            unsigned Depth) const {
  switch (MI.getOpcode()) {
  case TargetOpcode::G_SPLAT_VECTOR:
  case AArch64::G_SADDLP:
  case AArch64::G_UADDLP:
  case TargetOpcode::G_SITOFP:
  case TargetOpcode::G_UITOFP:
  case TargetOpcode::G_EXTRACT_VECTOR_ELT:
  case TargetOpcode::G_INSERT_VECTOR_ELT:
  case TargetOpcode::G_BUILD_VECTOR:
  case TargetOpcode::G_BUILD_VECTOR_TRUNC:
  case AArch64::G_SLI:
  case AArch64::G_SRI:
  case AArch64::G_FPTRUNC_ODD:
    return true;
  case TargetOpcode::G_INTRINSIC_W_SIDE_EFFECTS:
    switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
    case Intrinsic::aarch64_neon_ld1x2:
    case Intrinsic::aarch64_neon_ld1x3:
    case Intrinsic::aarch64_neon_ld1x4:
    case Intrinsic::aarch64_neon_ld2:
    case Intrinsic::aarch64_neon_ld2lane:
    case Intrinsic::aarch64_neon_ld2r:
    case Intrinsic::aarch64_neon_ld3:
    case Intrinsic::aarch64_neon_ld3lane:
    case Intrinsic::aarch64_neon_ld3r:
    case Intrinsic::aarch64_neon_ld4:
    case Intrinsic::aarch64_neon_ld4lane:
    case Intrinsic::aarch64_neon_ld4r:
      return true;
    default:
      break;
    }
    break;
  default:
    break;
  }
  return hasFPConstraints(MI, MRI, TRI, Depth);
}

bool AArch64RegisterBankInfo::prefersFPUse(const MachineInstr &MI,
                                           const MachineRegisterInfo &MRI,
                                           const AArch64RegisterInfo &TRI,
                                           unsigned Depth) const {
  switch (MI.getOpcode()) {
  case TargetOpcode::G_SITOFP:
  case TargetOpcode::G_UITOFP:
    return MRI.getType(MI.getOperand(0).getReg()).getSizeInBits() ==
           MRI.getType(MI.getOperand(1).getReg()).getSizeInBits();
  }
  return onlyDefinesFP(MI, MRI, TRI, Depth);
}

bool AArch64RegisterBankInfo::shouldUseFPRForCvtOperand(
    const MachineInstr &MI, bool BankedOpIsDef, bool ForceFPRForBankedOp16,
    bool ForceFPRForOtherOp16, bool AllowFPRCVT, bool CheckBankedOpUses) const {
  const MachineFunction &MF = *MI.getMF();
  const MachineRegisterInfo &MRI = MF.getRegInfo();
  const AArch64Subtarget &STI = MF.getSubtarget<AArch64Subtarget>();
  const AArch64RegisterInfo &TRI = *STI.getRegisterInfo();

  unsigned BankedOpIdx = BankedOpIsDef ? 0 : 2;
  unsigned OtherOpIdx = BankedOpIsDef ? 2 : 0;

  Register BankedReg = MI.getOperand(BankedOpIdx).getReg();
  if (MRI.getType(BankedReg).isVector())
    return true;

  TypeSize BankedSize = TRI.getRegSizeInBits(BankedReg, MRI);
  TypeSize OtherSize =
      TRI.getRegSizeInBits(MI.getOperand(OtherOpIdx).getReg(), MRI);
  if ((ForceFPRForBankedOp16 && BankedSize == 16) ||
      (ForceFPRForOtherOp16 && OtherSize == 16))
    return true;

  if (BankedSize != OtherSize && !AllowFPRCVT)
    return false;

  if (CheckBankedOpUses)
    return all_of(
        MRI.use_nodbg_instructions(BankedReg), [&](const MachineInstr &UseMI) {
          return onlyUsesFP(UseMI, MRI, TRI) || prefersFPUse(UseMI, MRI, TRI);
        });

  const MachineInstr *DefMI = MRI.getVRegDef(BankedReg);
  return DefMI &&
         (onlyUsesFP(*DefMI, MRI, TRI) || prefersFPUse(*DefMI, MRI, TRI));
}

bool AArch64RegisterBankInfo::isLoadFromFPType(const MachineInstr &MI) const {
  // GMemOperation because we also want to match indexed loads.
  auto *MemOp = cast<GMemOperation>(&MI);
  const Value *LdVal = MemOp->getMMO().getValue();
  if (!LdVal)
    return false;

  Type *EltTy = nullptr;
  if (const GlobalValue *GV = dyn_cast<GlobalValue>(LdVal)) {
    EltTy = GV->getValueType();
    // Look at the first element of the struct to determine the type we are
    // loading
    while (StructType *StructEltTy = dyn_cast<StructType>(EltTy)) {
      if (StructEltTy->getNumElements() == 0)
        break;
      EltTy = StructEltTy->getTypeAtIndex(0U);
    }
    // Look at the first element of the array to determine its type
    if (isa<ArrayType>(EltTy))
      EltTy = EltTy->getArrayElementType();
  } else if (!isa<Constant>(LdVal)) {
    // FIXME: grubbing around uses is pretty ugly, but with no more
    // `getPointerElementType` there's not much else we can do.
    for (const auto *LdUser : LdVal->users()) {
      if (isa<LoadInst>(LdUser)) {
        EltTy = LdUser->getType();
        break;
      }
      if (isa<StoreInst>(LdUser) && LdUser->getOperand(1) == LdVal) {
        EltTy = LdUser->getOperand(0)->getType();
        break;
      }
    }
  }
  return EltTy && EltTy->isFPOrFPVectorTy();
}

#define GET_TARGET_REGBANK_SEARCH_METHOD
#include "AArch64GenRegisterBank.inc"

const RegisterBankInfo::InstructionMapping &
AArch64RegisterBankInfo::getInstrMapping(const MachineInstr &MI) const {
  const unsigned Opc = MI.getOpcode();

  // Try the default logic for non-generic instructions that are either copies
  // or already have some operands assigned to banks.
  if ((Opc != TargetOpcode::COPY && !isPreISelGenericOpcode(Opc)) ||
      Opc == TargetOpcode::G_PHI) {
    const RegisterBankInfo::InstructionMapping &Mapping =
        getInstrMappingImpl(MI);
    if (Mapping.isValid())
      return Mapping;
  }

  if (const InstructionMapping &Mapping = getGeneratedInstrMapping(MI);
      Mapping.isValid())
    return Mapping;

  const MachineFunction &MF = *MI.getParent()->getParent();
  const MachineRegisterInfo &MRI = MF.getRegInfo();
  const AArch64Subtarget &STI = MF.getSubtarget<AArch64Subtarget>();
  const AArch64RegisterInfo &TRI = *STI.getRegisterInfo();

  switch (Opc) {
  case TargetOpcode::G_BITCAST: {
    Register SrcReg = MI.getOperand(1).getReg();
    const RegisterBank *SrcRB = getRegBank(SrcReg, MRI, TRI);
    if (SrcRB) {
      TypeSize Size = TRI.getRegSizeInBits(SrcReg, MRI);
      return getInstructionMapping(
          DefaultMappingID, 0,
          getCopyMapping(SrcRB->getID(), SrcRB->getID(), Size),
          // We only care about the mapping of the destination.
          /*NumOperands=*/2);
    }
    [[fallthrough]];
  }
  case TargetOpcode::COPY: {
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg = MI.getOperand(1).getReg();
    // Check if one of the register is not a generic register.
    if ((DstReg.isPhysical() || !MRI.getType(DstReg).isValid()) ||
        (SrcReg.isPhysical() || !MRI.getType(SrcReg).isValid())) {
      const RegisterBank *DstRB = getRegBank(DstReg, MRI, TRI);
      const RegisterBank *SrcRB = getRegBank(SrcReg, MRI, TRI);
      if (!DstRB)
        DstRB = SrcRB;
      else if (!SrcRB)
        SrcRB = DstRB;
      // If both RB are null that means both registers are generic.
      // We shouldn't be here.
      assert(DstRB && SrcRB && "Both RegBank were nullptr");
      TypeSize Size = TRI.getRegSizeInBits(DstReg, MRI);
      return getInstructionMapping(
          DefaultMappingID, copyCost(*DstRB, *SrcRB, Size),
          getCopyMapping(DstRB->getID(), SrcRB->getID(), Size),
          // We only care about the mapping of the destination.
          /*NumOperands*/ 1);
    }
    // Both registers are generic
    LLT DstTy = MRI.getType(MI.getOperand(0).getReg());
    LLT SrcTy = MRI.getType(MI.getOperand(1).getReg());
    TypeSize Size = DstTy.getSizeInBits();
    bool DstIsGPR = !DstTy.isVector() && DstTy.getSizeInBits() <= 64;
    bool SrcIsGPR = !SrcTy.isVector() && SrcTy.getSizeInBits() <= 64;
    const RegisterBank &DstRB =
        DstIsGPR ? AArch64::GPRRegBank : AArch64::FPRRegBank;
    const RegisterBank &SrcRB =
        SrcIsGPR ? AArch64::GPRRegBank : AArch64::FPRRegBank;
    return getInstructionMapping(
        DefaultMappingID, copyCost(DstRB, SrcRB, Size),
        getCopyMapping(DstRB.getID(), SrcRB.getID(), Size),
        // We only care about the mapping of the destination for COPY.
        /*NumOperands*/ Opc == TargetOpcode::G_BITCAST ? 2 : 1);
  }
  default:
    break;
  }

  unsigned NumOperands = MI.getNumOperands();
  unsigned MappingID = DefaultMappingID;

  // Track the size and bank of each register.  We don't do partial mappings.
  SmallVector<unsigned, 4> OpSize(NumOperands);
  SmallVector<unsigned, 4> OpRegBankIdx(NumOperands);
  for (unsigned Idx = 0; Idx < NumOperands; ++Idx) {
    auto &MO = MI.getOperand(Idx);
    if (!MO.isReg() || !MO.getReg())
      continue;

    LLT Ty = MRI.getType(MO.getReg());
    if (!Ty.isValid())
      continue;
    OpSize[Idx] = Ty.getSizeInBits().getKnownMinValue();

    // As a top-level guess, vectors including both scalable and non-scalable
    // ones go in FPRs, scalars and pointers in GPRs.
    // For floating-point instructions, scalars go in FPRs.
    if (Ty.isVector())
      OpRegBankIdx[Idx] = AArch64::FPRRegBankID;
    else if (isPreISelGenericFloatingPointOpcode(Opc) ||
             (MO.isDef() && onlyDefinesFP(MI, MRI, TRI)) ||
             (MO.isUse() && onlyUsesFP(MI, MRI, TRI)) ||
             Ty.getSizeInBits() > 64)
      OpRegBankIdx[Idx] = AArch64::FPRRegBankID;
    else
      OpRegBankIdx[Idx] = AArch64::GPRRegBankID;
  }

  unsigned Cost = 1;
  // Some of the floating-point instructions have mixed GPR and FPR operands:
  // fine-tune the computed mapping.
  switch (Opc) {
  case TargetOpcode::G_SPLAT_VECTOR: {
    Register ScalarReg = MI.getOperand(1).getReg();
    LLT ScalarTy = MRI.getType(ScalarReg);
    auto ScalarDef = MRI.getVRegDef(ScalarReg);
    // We want to select dup(load) into LD1R.
    if (ScalarDef->getOpcode() == TargetOpcode::G_LOAD)
      OpRegBankIdx = {AArch64::FPRRegBankID, AArch64::FPRRegBankID};
    else if (getRegBank(ScalarReg, MRI, TRI) == &AArch64::FPRRegBank ||
             onlyDefinesFP(*ScalarDef, MRI, TRI))
      OpRegBankIdx = {AArch64::FPRRegBankID, AArch64::FPRRegBankID};
    else {
      if (ScalarTy.getSizeInBits() < 32 &&
          getRegBank(ScalarReg, MRI, TRI) == &AArch64::GPRRegBank) {
        // Calls applyMappingImpl()
        MappingID = CustomMappingID;
      }
      OpRegBankIdx = {AArch64::FPRRegBankID, AArch64::GPRRegBankID};
    }
    break;
  }
  case TargetOpcode::G_TRUNC: {
    LLT SrcTy = MRI.getType(MI.getOperand(1).getReg());
    if (!SrcTy.isVector() && SrcTy.getSizeInBits() == 128)
      OpRegBankIdx = {AArch64::FPRRegBankID, AArch64::FPRRegBankID};
    break;
  }
  case TargetOpcode::G_SITOFP:
  case TargetOpcode::G_UITOFP: {
    if (MRI.getType(MI.getOperand(0).getReg()).isVector())
      break;
    // Integer to FP conversions don't necessarily happen between GPR -> FPR
    // regbanks. They can also be done within an FPR register.
    Register SrcReg = MI.getOperand(1).getReg();
    if (getRegBank(SrcReg, MRI, TRI) == &AArch64::FPRRegBank &&
        MRI.getType(SrcReg).getSizeInBits() ==
            MRI.getType(MI.getOperand(0).getReg()).getSizeInBits())
      OpRegBankIdx = {AArch64::FPRRegBankID, AArch64::FPRRegBankID};
    else
      OpRegBankIdx = {AArch64::FPRRegBankID, AArch64::GPRRegBankID};
    break;
  }
  case TargetOpcode::G_FPTOSI_SAT:
  case TargetOpcode::G_FPTOUI_SAT:
  case TargetOpcode::G_FPTOSI:
  case TargetOpcode::G_FPTOUI:
  case TargetOpcode::G_INTRINSIC_LRINT:
  case TargetOpcode::G_INTRINSIC_LLRINT:
  case TargetOpcode::G_LROUND:
  case TargetOpcode::G_LLROUND: {
    LLT DstType = MRI.getType(MI.getOperand(0).getReg());
    if (DstType.isVector())
      break;
    if (DstType == LLT::scalar(16)) {
      OpRegBankIdx = {AArch64::FPRRegBankID, AArch64::FPRRegBankID};
      break;
    }
    TypeSize DstSize = TRI.getRegSizeInBits(MI.getOperand(0).getReg(), MRI);
    TypeSize SrcSize = TRI.getRegSizeInBits(MI.getOperand(1).getReg(), MRI);
    if (((DstSize == SrcSize) || STI.hasFeature(AArch64::FeatureFPRCVT)) &&
        all_of(MRI.use_nodbg_instructions(MI.getOperand(0).getReg()),
               [&](const MachineInstr &UseMI) {
                 return onlyUsesFP(UseMI, MRI, TRI) ||
                        prefersFPUse(UseMI, MRI, TRI);
               }))
      OpRegBankIdx = {AArch64::FPRRegBankID, AArch64::FPRRegBankID};
    else
      OpRegBankIdx = {AArch64::GPRRegBankID, AArch64::FPRRegBankID};
    break;
  }
  case TargetOpcode::G_BITCAST:
    // This is going to be a cross register bank copy and this is expensive.
    if (OpRegBankIdx[0] != OpRegBankIdx[1])
      Cost = copyCost(getRegBank(OpRegBankIdx[0]), getRegBank(OpRegBankIdx[1]),
                      TypeSize::getFixed(OpSize[0]));
    break;
  case TargetOpcode::G_LOAD: {
    // Loading in vector unit is slightly more expensive.
    // This is actually only true for the LD1R and co instructions,
    // but anyway for the fast mode this number does not matter and
    // for the greedy mode the cost of the cross bank copy will
    // offset this number.
    // FIXME: Should be derived from the scheduling model.
    if (OpRegBankIdx[0] != AArch64::GPRRegBankID) {
      Cost = 2;
      break;
    }

    if (cast<GLoad>(MI).isAtomic()) {
      // Atomics always use GPR destinations. Don't refine any further.
      OpRegBankIdx[0] = AArch64::GPRRegBankID;
      if (MRI.getType(MI.getOperand(0).getReg()).getSizeInBits() < 32)
        MappingID = CustomMappingID;
      break;
    }

    // Try to guess the type of the load from the MMO.
    if (isLoadFromFPType(MI)) {
      OpRegBankIdx[0] = AArch64::FPRRegBankID;
      break;
    }

    // Check if that load feeds fp instructions.
    // In that case, we want the default mapping to be on FPR
    // instead of blind map every scalar to GPR.
    if (any_of(MRI.use_nodbg_instructions(MI.getOperand(0).getReg()),
               [&](const MachineInstr &UseMI) {
                 // If we have at least one direct or indirect use
                 // in a FP instruction,
                 // assume this was a floating point load in the IR. If it was
                 // not, we would have had a bitcast before reaching that
                 // instruction.
                 //
                 // Int->FP conversion operations are also captured in
                 // prefersFPUse().

                 if (isPHIWithFPConstraints(UseMI, MRI, TRI))
                   return true;

                 return onlyUsesFP(UseMI, MRI, TRI) ||
                        prefersFPUse(UseMI, MRI, TRI);
               }))
      OpRegBankIdx[0] = AArch64::FPRRegBankID;

    // On GPR, extend any load < 32bits to 32bit.
    LLT Ty = MRI.getType(MI.getOperand(0).getReg());
    if (Ty.isScalar() && Ty.getSizeInBits() < 32)
      MappingID = CustomMappingID;
    break;
  }
  case TargetOpcode::G_STORE:
    // Check if that store is fed by fp instructions.
    if (OpRegBankIdx[0] == AArch64::GPRRegBankID) {
      Register VReg = MI.getOperand(0).getReg();
      if (VReg) {
        MachineInstr *DefMI = MRI.getVRegDef(VReg);
        if (onlyDefinesFP(*DefMI, MRI, TRI)) {
          OpRegBankIdx[0] = AArch64::FPRRegBankID;
          break;
        }
      }

      // On GPR, extend any store < 32bits to 32bit.
      LLT Ty = MRI.getType(MI.getOperand(0).getReg());
      if (Ty.isScalar() && Ty.getSizeInBits() < 32)
        MappingID = CustomMappingID;
    }
    break;
  case TargetOpcode::G_INDEXED_STORE:
    if (OpRegBankIdx[1] == AArch64::GPRRegBankID) {
      Register VReg = MI.getOperand(1).getReg();
      if (!VReg)
        break;
      MachineInstr *DefMI = MRI.getVRegDef(VReg);
      if (onlyDefinesFP(*DefMI, MRI, TRI))
        OpRegBankIdx[1] = AArch64::FPRRegBankID;
      break;
    }
    break;
  case TargetOpcode::G_INDEXED_SEXTLOAD:
  case TargetOpcode::G_INDEXED_ZEXTLOAD:
    // These should always be GPR.
    OpRegBankIdx[0] = AArch64::GPRRegBankID;
    break;
  case TargetOpcode::G_INDEXED_LOAD: {
    if (isLoadFromFPType(MI))
      OpRegBankIdx[0] = AArch64::FPRRegBankID;
    break;
  }
  case TargetOpcode::G_SELECT: {
    // If the destination is FPR, preserve that.
    if (OpRegBankIdx[0] != AArch64::GPRRegBankID)
      break;

    // If we're taking in vectors, we have no choice but to put everything on
    // FPRs, except for the condition. The condition must always be on a GPR.
    LLT SrcTy = MRI.getType(MI.getOperand(2).getReg());
    if (SrcTy.isVector()) {
      OpRegBankIdx = {AArch64::FPRRegBankID, AArch64::GPRRegBankID,
                      AArch64::FPRRegBankID, AArch64::FPRRegBankID};
      break;
    }

    // Try to minimize the number of copies. If we have more floating point
    // constrained values than not, then we'll put everything on FPR. Otherwise,
    // everything has to be on GPR.
    unsigned NumFP = 0;

    // Check if the uses of the result always produce floating point values.
    //
    // For example:
    //
    // %z = G_SELECT %cond %x %y
    // fpr = G_FOO %z ...
    if (any_of(MRI.use_nodbg_instructions(MI.getOperand(0).getReg()),
               [&](MachineInstr &MI) { return onlyUsesFP(MI, MRI, TRI); }))
      ++NumFP;

    // Check if the defs of the source values always produce floating point
    // values.
    //
    // For example:
    //
    // %x = G_SOMETHING_ALWAYS_FLOAT %a ...
    // %z = G_SELECT %cond %x %y
    //
    // Also check whether or not the sources have already been decided to be
    // FPR. Keep track of this.
    //
    // This doesn't check the condition, since it's just whatever is in NZCV.
    // This isn't passed explicitly in a register to fcsel/csel.
    for (unsigned Idx = 2; Idx < 4; ++Idx) {
      Register VReg = MI.getOperand(Idx).getReg();
      MachineInstr *DefMI = MRI.getVRegDef(VReg);
      if (getRegBank(VReg, MRI, TRI) == &AArch64::FPRRegBank ||
          onlyDefinesFP(*DefMI, MRI, TRI))
        ++NumFP;
    }

    // If we have more FP constraints than not, then move everything over to
    // FPR.
    if (NumFP >= 2)
      OpRegBankIdx = {AArch64::FPRRegBankID, AArch64::GPRRegBankID,
                      AArch64::FPRRegBankID, AArch64::FPRRegBankID};

    break;
  }
  case TargetOpcode::G_UNMERGE_VALUES: {
    // If the first operand belongs to a FPR register bank, then make sure that
    // we preserve that.
    if (OpRegBankIdx[0] != AArch64::GPRRegBankID)
      break;

    LLT SrcTy = MRI.getType(MI.getOperand(MI.getNumOperands()-1).getReg());
    // UNMERGE into scalars from a vector should always use FPR.
    // Likewise if any of the uses are FP instructions.
    if (SrcTy.isVector() || SrcTy == LLT::scalar(128) ||
        any_of(MRI.use_nodbg_instructions(MI.getOperand(0).getReg()),
               [&](MachineInstr &MI) { return onlyUsesFP(MI, MRI, TRI); })) {
      // Set the register bank of every operand to FPR.
      for (unsigned Idx = 0, NumOperands = MI.getNumOperands();
           Idx < NumOperands; ++Idx)
        OpRegBankIdx[Idx] = AArch64::FPRRegBankID;
    }
    break;
  }
  case AArch64::G_SQSHLU_I:
    // Destination and source need to be FPRs.
    OpRegBankIdx[0] = AArch64::FPRRegBankID;
    OpRegBankIdx[1] = AArch64::FPRRegBankID;

    // Shift Index needs to be a GPR.
    OpRegBankIdx[2] = AArch64::GPRRegBankID;
    break;
  case TargetOpcode::G_EXTRACT: {
    // For s128 sources we have to use fpr unless we know otherwise.
    auto Src = MI.getOperand(1).getReg();
    LLT SrcTy = MRI.getType(MI.getOperand(1).getReg());
    if (SrcTy.getSizeInBits() != 128)
      break;
    auto Idx = MRI.getRegClassOrNull(Src) == &AArch64::XSeqPairsClassRegClass
                   ? AArch64::GPRRegBankID
                   : AArch64::FPRRegBankID;
    OpRegBankIdx[0] = Idx;
    OpRegBankIdx[1] = Idx;
    break;
  }
  case TargetOpcode::G_BUILD_VECTOR: {
    // If the first source operand belongs to a FPR register bank, then make
    // sure that we preserve that.
    if (OpRegBankIdx[1] != AArch64::GPRRegBankID)
      break;
    Register VReg = MI.getOperand(1).getReg();
    if (!VReg)
      break;

    // Get the instruction that defined the source operand reg, and check if
    // it's a floating point operation. Or, if it's a type like s16 which
    // doesn't have a exact size gpr register class. The exception is if the
    // build_vector has all constant operands, which may be better to leave as
    // gpr without copies, so it can be matched in imported patterns.
    MachineInstr *DefMI = MRI.getVRegDef(VReg);
    unsigned DefOpc = DefMI->getOpcode();
    const LLT SrcTy = MRI.getType(VReg);
    if (all_of(MI.operands(), [&](const MachineOperand &Op) {
          APInt Cst;
          return Op.isDef() || mi_match(Op.getReg(), MRI, m_ICst(Cst));
        }))
      break;
    if (isPreISelGenericFloatingPointOpcode(DefOpc) ||
        SrcTy.getSizeInBits() < 32 ||
        getRegBank(VReg, MRI, TRI) == &AArch64::FPRRegBank) {
      // Have a floating point op.
      // Make sure every operand gets mapped to a FPR register class.
      unsigned NumOperands = MI.getNumOperands();
      for (unsigned Idx = 0; Idx < NumOperands; ++Idx)
        OpRegBankIdx[Idx] = AArch64::FPRRegBankID;
    }
    break;
  }
  case TargetOpcode::G_INTRINSIC:
  case TargetOpcode::G_INTRINSIC_W_SIDE_EFFECTS: {
    switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
    case Intrinsic::aarch64_neon_fcvtas:
    case Intrinsic::aarch64_neon_fcvtau:
    case Intrinsic::aarch64_neon_fcvtzs:
    case Intrinsic::aarch64_neon_fcvtzu:
    case Intrinsic::aarch64_neon_fcvtms:
    case Intrinsic::aarch64_neon_fcvtmu:
    case Intrinsic::aarch64_neon_fcvtns:
    case Intrinsic::aarch64_neon_fcvtnu:
    case Intrinsic::aarch64_neon_fcvtps:
    case Intrinsic::aarch64_neon_fcvtpu: {
      OpRegBankIdx[2] = AArch64::FPRRegBankID;
      if (shouldUseFPRForCvtOperand(MI, /*BankedOpIsDef=*/true,
                                    /*ForceFPRForBankedOp16=*/true,
                                    /*ForceFPRForOtherOp16=*/false,
                                    /*AllowFPRCVT=*/STI.hasFPRCVT(),
                                    /*CheckBankedOpUses=*/true))
        OpRegBankIdx[0] = AArch64::FPRRegBankID;
      else
        OpRegBankIdx[0] = AArch64::GPRRegBankID;
      break;
    }
    case Intrinsic::aarch64_neon_vcvtfxs2fp:
    case Intrinsic::aarch64_neon_vcvtfxu2fp: {
      OpRegBankIdx[0] = AArch64::FPRRegBankID;
      if (shouldUseFPRForCvtOperand(MI, /*BankedOpIsDef=*/false,
                                    /*ForceFPRForBankedOp16=*/false,
                                    /*ForceFPRForOtherOp16=*/true,
                                    /*AllowFPRCVT=*/false,
                                    /*CheckBankedOpUses=*/false))
        OpRegBankIdx[2] = AArch64::FPRRegBankID;
      else
        OpRegBankIdx[2] = AArch64::GPRRegBankID;
      break;
    }
    case Intrinsic::aarch64_neon_vcvtfp2fxs:
    case Intrinsic::aarch64_neon_vcvtfp2fxu: {
      OpRegBankIdx[2] = AArch64::FPRRegBankID;
      if (shouldUseFPRForCvtOperand(MI, /*BankedOpIsDef=*/true,
                                    /*ForceFPRForBankedOp16=*/false,
                                    /*ForceFPRForOtherOp16=*/true,
                                    /*AllowFPRCVT=*/false,
                                    /*CheckBankedOpUses=*/true))
        OpRegBankIdx[0] = AArch64::FPRRegBankID;
      else
        OpRegBankIdx[0] = AArch64::GPRRegBankID;
      break;
    }
    default: {
      // Check if we know that the intrinsic has any constraints on its register
      // banks. If it does, then update the mapping accordingly.
      unsigned Idx = 0;
      if (onlyDefinesFP(MI, MRI, TRI))
        for (const auto &Op : MI.defs()) {
          if (Op.isReg())
            OpRegBankIdx[Idx] = AArch64::FPRRegBankID;
          ++Idx;
        }
      else
        Idx += MI.getNumExplicitDefs();

      if (onlyUsesFP(MI, MRI, TRI))
        for (const auto &Op : MI.explicit_uses()) {
          if (Op.isReg())
            OpRegBankIdx[Idx] = AArch64::FPRRegBankID;
          ++Idx;
        }
      break;
    }
    }
    break;
  }
  }

  // Finally construct the computed mapping.
  SmallVector<const ValueMapping *, 8> OpdsMapping(NumOperands);
  for (unsigned Idx = 0; Idx < NumOperands; ++Idx) {
    if (MI.getOperand(Idx).isReg() && MI.getOperand(Idx).getReg()) {
      LLT Ty = MRI.getType(MI.getOperand(Idx).getReg());
      if (!Ty.isValid())
        continue;
      auto Mapping = AArch64::getGeneratedValueMapping(
          OpRegBankIdx[Idx], TypeSize::getFixed(OpSize[Idx]));
      if (!Mapping->isValid())
        return getInvalidInstructionMapping();

      OpdsMapping[Idx] = Mapping;
    }
  }

  return getInstructionMapping(MappingID, Cost, getOperandsMapping(OpdsMapping),
                               NumOperands);
}
